#[derive(Debug, Clone)]
pub struct PeerEndpoint {
    pub addr: SocketAddr,
    pub source: RouteSource,
    pub last_seen: Instant,
    pub last_authenticated: Option<Instant>,
    /// Round trip of a nonce-bound signed discovery reply at last_seen.
    pub routed_rtt: Option<Duration>,
    /// Public observation deadline for authenticated/directory evidence, never a route lease.
    pub presence_expires_at: Option<Instant>,
    /// Original directory expiry in Unix seconds, retained across repeated old-relay evidence.
    pub presence_origin_expires_at: Option<u64>,
    /// Trusted directory forwarding distance; zero denotes a direct registration.
    pub origin_hops: Option<u8>,
    /// Optional consented registration relationship; never routing authority.
    pub registration_origin: Option<crate::node::RegistrationOrigin>,
}

impl PeerEndpoint {
    /// Physical LAN observations expire promptly. Other public paths tolerate
    /// loss for two minutes; private traffic and repeated directory metadata
    /// cannot move the original observation deadline.
    pub fn reconnect_remaining(&self, now: Instant) -> Duration {
        self.routes
            .iter()
            .filter_map(|route| {
                route.public_presentation_deadline(self.routes.iter().any(|other| {
                    other.source == RouteSource::Lan && other.addr.ip() == route.addr.ip()
                }))
            })
            .map(|deadline| deadline.saturating_duration_since(now))
            .max()
            .unwrap_or(Duration::ZERO)
    }

    /// Age of the newest original public observation, never a private route refresh.
    pub fn public_observation_age(&self, now: Instant) -> Option<Duration> {
        self.routes
            .iter()
            .filter_map(|route| {
                let deadline = route.public_presence_deadline()?;
                let observed = match route.source {
                    RouteSource::Authenticated | RouteSource::PostOffice => {
                        deadline.checked_sub(PUBLIC_PRESENCE_TTL)?
                    }
                    _ => route.last_seen,
                };
                Some(now.saturating_duration_since(observed))
            })
            .min()
    }

    /// A known application route without an intermediate Mesh Talk post office.
    /// Discovery is a candidate; transport still verifies reachability and identity.
    pub fn has_direct_route(&self) -> bool {
        self.routes.iter().any(|route| {
            matches!(
                route.source,
                RouteSource::Lan
      // A consumed deadline stays parked on a failed read. The existing
      // activation and recovery refreshes retry it without a zero-delay loop.
      if (next === deadline) return;
      if (timer !== undefined) clearTimeout(timer);
      timer = undefined;
      deadline = next;
      if (next !== Infinity) arm();
    },
    stop() {
      if (timer !== undefined) clearTimeout(timer);
    },
  };
}
